    // In a real attack, malicious input like:
    // "1' UNION SELECT username,password,email FROM users--"
    // would exploit this vulnerability

    echo "Simulated result: [Training data only]\n";
    return [
        ['username' => 'demo_user1', 'email' => 'demo@example.com'],
        ['username' => 'demo_user2', 'email' => 'demo2@example.com']
    ];
}

// Demonstrate the concept without actual exploitation
